semaphore mutex = 1, empty = n, full = 0;
item buffer[n];
int in = 0, out = 0;
producer() {
  while (1) {
    生产一个产品 x;
    P(empty);
    P(mutex);
    buffer[in] = x; in = (in + 1) % n;
    V(mutex);
    V(full);
  }
}
consumer() {
  while (1) {
    P(full);
    P(mutex);
    x = buffer[out]; out = (out + 1) % n;
    V(mutex);
    V(empty);
    消费产品 x;
  }
}

