}

semaphore customers = 0;  // 等候的顾客
semaphore barber = 0;     // 理发师就绪
semaphore mutex = 1;      // 保护 waiting
int waiting = 0;          // 等候人数
Barber() {
  while (1) {
    P(customers);         // 没有顾客就睡觉
    P(mutex);
    waiting--;
    V(barber);            // 叫一位顾客理发
    V(mutex);
    理发;
  }
}
Customer() {
  P(mutex);
  if (waiting < n) {
    waiting++;
    V(customers);         // 唤醒理发师
    V(mutex);
    P(barber);            // 等理发师
    接受理发;
  } else {
    V(mutex);             // 没有空椅子，离开
  }
}

semaphore empty1 = 1, full1 = 0;   // 缓冲区 B1
semaphore empty2 = 1, full2 = 0;   // 缓冲区 B2
get() {
  while (1) {
    从输入设备读一条记录 r;
    P(empty1); 把 r 放入 B1; V(full1);
  }
}
copy() {
  while (1) {
    P(full1); 从 B1 取出记录 r; V(empty1);
    P(empty2); 把 r 放入 B2; V(full2);
  }
}
put() {
  while (1) {
    P(full2); 从 B2 取出记录 r; V(empty2);
    打印 r;
  }
}
